cd /filesystem && python3 - <<'PY'
import openpyxl,re
for fn in ['Queue/2025-07-14_Active_Queue_Report.xlsx','Queue/2025-07-14_On_Hold_Queue_Report.xlsx']:
    wb=openpyxl.load_workbook(fn,data_only=True)
    print('####',fn)
    for ws in wb.worksheets:
        print('---',ws.title, ws.max_row)
        for row in ws.iter_rows(values_only=True):
            s=' | '.join('' if v is None else str(v) for v in row)
            if re.search(r'860|720|510|640|980|560|ALN-137|ALN-152|ALN-176|0779|0793',s):
                print(s)
PY

