import openpyxl
for fn in ['Standards/CEL-2025-Q2_Certified_Equipment_List.xlsx','Standards/Superseded/CEL-2024-Q4_Certified_Equipment_List.xlsx']:
    wb=openpyxl.load_workbook(fn,data_only=True)
    print('###',fn, wb.sheetnames)
    for tab in ['Inverters','Power Control Systems']:
        ws=wb[tab]
        print('--',tab, ws.max_row)
        for r in range(1,ws.max_row+1):
            vals=[ws.cell(r,c).value for c in range(1,7)]
            if tab=='Inverters' and vals[1] and any(x in str(vals[1]) for x in ['SM-215','SM-245','TE-180','VX-140','SV-720','Arvexa']):
                print(r,vals)
            if tab=='Power Control Systems' and vals[1] and any(x in str(vals[1]) for x in ['Arvexa','SV-720']):
                print(r,vals)
PY

