import openpyxl
for fn in ['Standards/CEL-2025-Q2_Certified_Equipment_List.xlsx','Standards/Superseded/CEL-2024-Q4_Certified_Equipment_List.xlsx']:
    wb=openpyxl.load_workbook(fn,data_only=True)
    hits=[]
    for ws in wb.worksheets:
        for row in ws.iter_rows(values_only=True):
            s=' | '.join('' if v is None else str(v) for v in row)
            if 'arvexa' in s.lower() or 'selvix' in s.lower(): hits.append((ws.title,s))
    print(fn, 'hits:', hits)
PY

