#!/usr/bin/env python3
"""Independent check of the municipal witness-test package against the CEL, checklist records,
requirements register, case read-back, schedule and DOCX schema."""
import csv, json, os, re, subprocess, sys, datetime
from docx import Document
import openpyxl

ROOT='/filesystem'
DOCX='/tmp/ahpele/Municipal_Witness_Test_Package.docx'
CEL_Q2=os.path.join(ROOT,'Standards/CEL-2025-Q2_Certified_Equipment_List.xlsx')
CEL_Q4=os.path.join(ROOT,'Standards/Superseded/CEL-2024-Q4_Certified_Equipment_List.xlsx')
REQ='/tmp/ahpele/requirements.csv'
CASE='/tmp/ahpele/case_readback.json'

errors=[]
def check(cond,msg):
    if not cond: errors.append(msg)

def norm(s):
    return re.sub(r'\s+',' ',str(s)).strip()

def cellrows(table):
    return [[norm(c.text) for c in row.cells] for row in table.rows]

def load_cel(path):
    wb=openpyxl.load_workbook(path,data_only=True)
    models={}
    for tab in ['Inverters','Power Control Systems']:
        ws=wb[tab]
        for r in range(2,ws.max_row+1):
            man=ws.cell(r,1).value; model=ws.cell(r,2).value
            if man and model:
                models[str(model).strip().upper()]={'manufacturer':str(man).strip(),'model':str(model).strip(),
                    'kw':ws.cell(r,3).value,'basis':ws.cell(r,4).value,'effective':ws.cell(r,5).value,
                    'row':r,'tab':tab}
    return models

q2=load_cel(CEL_Q2); q4=load_cel(CEL_Q4)

