                hits.append((i,s))
        if hits:
            print('--- sheet',ws.title)
            # print header
            if rows: print('HEADER:', ' | '.join('' if v is None else str(v) for v in rows[0]))
            for i,s in hits: print(i, s[:1000])
EOF

